create table if not exists public.member_suggestions (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,message text not null check(char_length(trim(message)) between 5 and 2000),is_anonymous boolean not null default false,status text not null default 'baru' check(status in ('baru','diproses','selesai')),admin_reply text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.marawis_quizzes (id bigint generated by default as identity primary key,title text not null check(char_length(trim(title)) between 3 and 120),description text,duration_minutes int not null default 10 check(duration_minutes between 1 and 180),published boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),starts_at timestamptz,ends_at timestamptz);
create table if not exists public.marawis_quiz_questions (id bigint generated by default as identity primary key,quiz_id bigint not null references public.marawis_quizzes(id) on delete cascade,question_text text not null,options jsonb not null check(jsonb_typeof(options)='array' and jsonb_array_length(options)=4),sort_order int not null default 0);
create table if not exists public.marawis_quiz_answers (question_id bigint primary key references public.marawis_quiz_questions(id) on delete cascade,correct_index int not null check(correct_index between 0 and 3));
create table if not exists public.marawis_quiz_attempts (id bigint generated by default as identity primary key,quiz_id bigint not null references public.marawis_quizzes(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,answers jsonb not null default '[]'::jsonb,score int not null default 0 check(score between 0 and 100),total_questions int not null default 0,started_at timestamptz not null default now(),submitted_at timestamptz not null default now(),unique(quiz_id,user_id));
create table if not exists public.marawis_game_scores (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,game_key text not null,score int not null default 0,created_at timestamptz not null default now());
alter table public.member_suggestions enable row level security; alter table public.marawis_quizzes enable row level security; alter table public.marawis_quiz_questions enable row level security; alter table public.marawis_quiz_answers enable row level security; alter table public.marawis_quiz_attempts enable row level security; alter table public.marawis_game_scores enable row level security;
create policy suggestions_insert_own on public.member_suggestions for insert to authenticated with check(user_id=(select auth.uid()));
create policy suggestions_read_own_or_admin on public.member_suggestions for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy suggestions_admin_update on public.member_suggestions for update to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina'))) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy quizzes_read_published_or_admin on public.marawis_quizzes for select to authenticated using(published or created_by=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy quizzes_admin_insert on public.marawis_quizzes for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy quizzes_admin_update on public.marawis_quizzes for update to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina'))) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy quizzes_admin_delete on public.marawis_quizzes for delete to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy questions_read_available on public.marawis_quiz_questions for select to authenticated using(exists(select 1 from public.marawis_quizzes q where q.id=quiz_id and (q.published or q.created_by=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')))));
create policy questions_admin_insert on public.marawis_quiz_questions for insert to authenticated with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy questions_admin_delete on public.marawis_quiz_questions for delete to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy answers_admin_only on public.marawis_quiz_answers for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina'))) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy attempts_read_own_or_admin on public.marawis_quiz_attempts for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('pengurus','pembina')));
create policy attempts_insert_own on public.marawis_quiz_attempts for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.marawis_quizzes q where q.id=quiz_id and q.published));
create policy game_scores_read on public.marawis_game_scores for select to authenticated using(true);
create policy game_scores_insert_own on public.marawis_game_scores for insert to authenticated with check(user_id=(select auth.uid()));
grant select,insert,update on public.member_suggestions to authenticated; grant select,insert,update,delete on public.marawis_quizzes to authenticated; grant select,insert,delete on public.marawis_quiz_questions to authenticated; grant select,insert,update,delete on public.marawis_quiz_answers to authenticated; grant select,insert on public.marawis_quiz_attempts to authenticated; grant select,insert on public.marawis_game_scores to authenticated; grant usage,select on all sequences in schema public to authenticated;